import type { Unit } from './ingredient-parser';

/**
 * Maps the Bulgarian words of an ingredient line to a food in the seed catalogue
 * (`seed-data/foods.ts` and `foods.cooking.ts`) and gives the weights needed to turn
 * household measures into grams.
 */
export interface IngredientEntry {
  /** English catalogue name. Every entry is checked against the seed in tests. */
  food: string;
  /**
   * Word stems, lower-case. A stem matches a word by prefix ("домат" matches "домати", "доматите").
   * A stem with spaces must match consecutive words. The entry with the most words, then the longest
   * stem, wins, so "кисело мляко" beats "мляко" and "доматено пюре" beats "домат".
   */
  stems: string[];
  /** Grams of one countable unit (a piece, head, bunch, slice, pack...). A bare number ("3 яйца") uses `piece`. */
  unitG?: Partial<Record<Unit, number>>;
  /** Grams per millilitre for spoons, cups and ml. Default 1 (water-like). */
  gPerMl?: number;
  /** Grams assumed when the line has no amount ("сол", "магданоз", "олио за пържене"). Without it the line is skipped. */
  defaultG?: number;
}

const SPICE = { unitG: { pinch: 0.4, pack: 10, grain: 0.1, leaf: 0.5, piece: 0.2 }, gPerMl: 0.5, defaultG: 2 } as const;
const HERB = { unitG: { bunch: 30, stalk: 3, leaf: 0.5, pinch: 0.5 }, gPerMl: 0.2, defaultG: 10 } as const;
